  function metatron(size, color, w) {
    var k = stroke(color), pts = [[50, 50]], c = '', l = '';
    for (var i = 0; i < 6; i++) { var a = (i * 60 - 90) * Math.PI / 180; pts.push([50 + 20 * Math.cos(a), 50 + 20 * Math.sin(a)]); pts.push([50 + 40 * Math.cos(a), 50 + 40 * Math.sin(a)]); }
    pts.forEach(function (p) { c += '<circle cx="' + p[0].toFixed(2) + '" cy="' + p[1].toFixed(2) + '" r="6.5"/>'; });
    for (var x = 0; x < pts.length; x++) for (var y = x + 1; y < pts.length; y++) l += '<line x1="' + pts[x][0].toFixed(2) + '" y1="' + pts[x][1].toFixed(2) + '" x2="' + pts[y][0].toFixed(2) + '" y2="' + pts[y][1].toFixed(2) + '"/>';
    return '<svg width="' + size + '" height="' + size + '" viewBox="0 0 100 100">' + k.defs + '<g fill="none" stroke="' + k.s + '" stroke-width="' + (w || .6) + '" opacity=".9">' + l + c + '</g></svg>';
  }
