    for (var i = 0; i < 6; i++) { var a = (-90 + i * 60) * Math.PI / 180; v += '<circle cx="' + (50 + R * Math.cos(a)).toFixed(2) + '" cy="' + (50 + R * Math.sin(a)).toFixed(2) + '" r="3"/>'; }
    return '<svg width="' + size + '" height="' + size + '" viewBox="0 0 100 100">' + k.defs + '<g fill="none" stroke="' + k.s + '" stroke-width="' + (w || 1.2) + '"><circle cx="50" cy="50" r="46"/><circle cx="50" cy="50" r="' + R + '"/><polygon points="' + tri(-90) + '"/><polygon points="' + tri(90) + '"/><circle cx="50" cy="50" r="12"/>' + v + '</g></svg>';
  }
  // MCC crystal mark: the owned logo geometry (client-public/src/components/mcc-icon-*.svg).
  function logo(w, h, white) {
