      '<mask id="m' + id + '" maskUnits="userSpaceOnUse" x="0" y="0" width="500" height="690"><polygon points="250.86 18.97 492.36 341.89 251.9 671.03 6.95 343.62" fill="white"/><g stroke="black" stroke-width="10" stroke-linecap="round" fill="none"><line x1="250.86" y1="18.97" x2="124.25" y2="396.06"/><line x1="250.86" y1="18.97" x2="249.83" y2="372.6"/><line x1="250.86" y1="18.97" x2="374.37" y2="396.75"/><polyline points="124.25 396.06 249.83 372.6 374.37 396.75"/><line x1="6.95" y1="343.62" x2="124.25" y2="396.06"/><line x1="492.36" y1="341.89" x2="374.37" y2="396.75"/><line x1="124.25" y1="396.06" x2="251.9" y2="671.02"/><line x1="249.83" y1="372.6" x2="251.9" y2="671.02"/><line x1="374.37" y1="396.75" x2="251.9" y2="671.02"/></g></mask></defs>' +
