  var L = {
    cover: function () {
      var g = d.glyph || 'transmutation';
      var focal = g === 'crystal' ? logo(190, 262) : g === 'seed' ? seed(260, 'gradient', 1.4) : g === 'metatron' ? metatron(280, 'gradient', .7) : transmutation(260, 'gradient', 1.4);
      var px = tier(d.headline, [[28, 132], [44, 112], [60, 96]]);
