        '<div class="layer" style="display:grid;place-items:start center;padding-top:-20px"><div style="margin-top:-20px;transform:rotate(' + ((d.index || 1) * 7 % 15) + 'deg)">' + seed(980, '#b7a3e6', .25, .10) + '</div></div>' +
        '<div class="focal">' + focal + '</div>' +
        (d.eyebrow ? '<div class="pill">' + esc(d.eyebrow) + '</div>' : '') +
        '<div class="headline"><h1 class="display balance" style="font-size:' + px + 'px">' + rich(d.headline) + '</h1></div>' +
        (d.sub ? '<p class="sub balance">' + rich(d.sub) + '</p>' : '') +
        '<div class="swipe">' + T.swipe + '</div>' + footer({ dark: true, noHandle: true }) + '</section>';
    },
    statement: function () {
