        '<div class="box"><div class="eyebrow">' + esc(eyebrowText()) + '</div>' +
        '<div class="grow"><h2 class="display text balance" style="font-size:' + px + 'px">' + rich(d.statement) + '</h2>' +
        (d.support ? '<p class="support">' + rich(d.support) + '</p>' : '') + '</div></div>' +
        '<div class="motif-corner">' + seed(220, '#66369b', 1.2) + '</div>' + footer() + '</section>';
    },
    list: function () {
      var items = (d.items || []).slice(0, 5), big = items.length < 5, fs = big ? 40 : 34;
      return '<section class="slide paper list"><div class="box"><div class="eyebrow">' + esc(eyebrowText()) + '</div>' +
        '<h2 class="display title balance" style="font-size:' + (AR ? 59 : 72) + 'px">' + rich(d.title) + '</h2><div class="grow"><ol>' +
        items.map(function (it, i) { return '<li><span class="disc">' + num(i + 1) + '</span><div><div class="item" style="font-size:' + fs + 'px">' + rich(it.text) + '</div>' + (it.sub ? '<div class="itemsub">' + rich(it.sub) + '</div>' : '') + '</div></li>'; }).join('') +
