      return '<section class="slide scene quote">' + stars(1350, d.index) + '<div class="orb"></div><div class="box center">' +
        (d.eyebrow ? '<div class="eyebrow">' + esc(eyebrowText()) + '</div>' : '') +
        '<div class="mark em">' + (AR ? '”' : '“') + '</div><p class="q balance" style="font-size:' + px + 'px">' + rich(d.question) + '</p>' +
