        '<h2 class="display behavior balance" style="font-size:' + (AR ? 62 : 76) + 'px">' + rich(d.behavior) + '</h2><div class="rule"></div>' +
        '<div class="label mono">' + T.differentReasons + '</div><div class="cards">' +
        (d.reasons || []).slice(0, 3).map(function (r, i) { return '<div class="card">' + glyphs[i] + '<p>' + rich(r) + '</p></div>'; }).join('') +
