        return '<section class="slide scene centers">' + stars(1350, d.index) + '<div class="box"><div class="eyebrow">' + esc(eyebrowText()) + '</div></div>' +
          '<div class="solo"><div class="bignode" style="color:' + (CHAKRA[c.key] || '#8a6dc9') + '"></div><div class="name">' + esc(c.name) + '</div>' +
          '<span class="chip" style="background:' + sc + '29"><b style="background:' + sc + '"></b>' + esc(T.states[c.state] || c.state) + '</span>' +
          '<div class="scale"><i style="left:calc(' + pin + '% - 15px)"></i></div><div class="scale-labels"><span>' + (AR ? 'انغلاق' : 'SHUTDOWN') + '</span><span>' + (AR ? 'جهد زائد' : 'OVER-EFFORT') + '</span></div>' +
          (c.note ? '<p class="body balance">' + rich(c.body || c.note) + '</p>' : '') + '</div>' +
          '<div class="footnote">' + T.footnote + '</div>' + footer({ dark: true }) + '</section>';
      }
      return '<section class="slide scene centers">' + stars(1350, d.index) + '<div class="box"><div class="eyebrow">' + esc(eyebrowText()) + '</div>' +
        (d.title ? '<h2 class="display title balance" style="font-size:' + (AR ? 52 : 64) + 'px">' + rich(d.title) + '</h2>' : '') + '</div>' +
        '<div class="spine"></div><div class="rows">' + rows.map(function (c) {
          var sc = STATE_COLOR[c.state] || '#5cc4cc';
          return '<div class="row"><div class="node" style="color:' + (CHAKRA[c.key] || '#8a6dc9') + '"><i></i></div><div class="name">' + esc(c.name) + '</div><div>' +
            '<span class="chip" style="background:' + sc + '29"><b style="background:' + sc + '"></b>' + esc(T.states[c.state] || c.state) + '</span>' +
