    },
    sample: function () {
      return '<section class="slide paper sample"><div class="box center"><div class="eyebrow">' + esc(eyebrowText()) + '</div>' +
        '<h2 class="display title balance" style="font-size:' + (AR ? 59 : 72) + 'px">' + rich(d.title) + '</h2></div>' +
        '<div class="frame"><img src="' + esc(d.image) + '" alt=""></div>' +
        (d.callout ? '<div class="callout">' + rich(d.callout) + '</div>' : '') +
        '<div class="label mono">' + T.sampleLabel + '</div>' + footer() + '</section>';
    },
    cta: function () {
      var offer = d.offer || 'both';
      var lite = '<div class="price' + (offer === 'lite' ? ' single' : '') + '"><div class="tier">' + T.lite + '</div><div class="amt"><bdi>' + PRICES.lite + '</bdi></div><div class="what">' + T.liteWhat + '</div></div>';
      var full = '<div class="price featured' + (offer === 'full' ? ' single' : '') + '"><div class="tier">' + T.full + '</div><div class="amt"><bdi>' + PRICES.full + '</bdi></div>' +
        (PRICES.launch ? '<div><span class="was"><bdi>' + PRICES.fullList + '</bdi></span><span class="offer">' + T.launch + '</span></div>' : '') + '<div class="what">' + T.fullWhat + '</div></div>';
      return '<section class="slide scene dawn cta">' + stars(1350, d.index) + '<div class="box center" style="top:90px">' +
        '<div class="logo">' + logo(88, 121) + '</div><div class="display tagline">' + rich(d.tagline || T.tagline) + '</div>' +
