";
const { post } = $input.first().json;
return post.slides.map((slide, i) => {
  const html = TEMPLATE.replace('__MCC_DATA__', JSON.stringify(slide).replace(/<//g, '<\/'));
  return { json: { n: i + 1, post_id: post.post_id }, binary: { data: { data: Buffer.from(html).toString('base64'), mimeType: 'text/html', fileName: 'index.html' } } };
});

// Gathers the 8 rendered JPEGs onto one item (slide_1..slide_8) and builds a contact-sheet page
// for the Telegram approval preview.
const items = $input.all();
const binary = {};
const thumbs = [];
for (let i = 0; i < items.length; i++) {
  binary[`slide_${i + 1}`] = items[i].binary.data;
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  thumbs.push(`<img src="data:image/jpeg;base64,${buf.toString('base64')}">`);
}
const sheet = `<!doctype html><html><head><meta charset="utf-8"><style>
body{margin:0;background:#0a0a1a;width:1080px}div{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;padding:8px}
img{width:100%;display:block;border-radius:6px}</style></head><body><div>${thumbs.join('')}</div>
<script>Promise.all([...document.images].map(i=>i.decode())).then(()=>document.body.setAttribute('data-ready','1'))</script></body></html>`;
binary.data = { data: Buffer.from(sheet).toString('base64'), mimeType: 'text/html', fileName: 'index.html' };
return [{ json: { post: $('Format?').first().json.post, slide_count: items.length }, binary }];

// Re-attaches the slides (HTTP nodes only return their own response) and adds the contact sheet.
const collected = $('Collect slides').first();
const binary = { ...collected.binary, sheet: $input.first().binary.data };
delete binary.data;
const keys = Object.keys(binary).filter((k) => k.startsWith('slide_')).sort((a, b) => Number(a.split('_')[1]) - Number(b.split('_')[1]));
return [{ json: { post: collected.json.post, qa_keys: keys, media_type: 'image/jpeg' }, binary }];

// One item per reel beat, rendered 1080x1920 with the reel_cover layout. In the premium tier the
// beats are transparent overlays laid over the AI clip by mcc-reel.
const TEMPLATE = "<!doctype html>
<meta charset="utf-8">
<!--
  My Crystal Code — social slide template (carousels 1080x1350, reel covers 1080x1920).

  One file renders every layout in English or Arabic. n8n injects the slide JSON by replacing
  the data token inside <script id="mcc-data"> (escape "</" as "<\/"), sends the HTML to the renderer, and waits
  for `body[data-ready="1"]` (set after web fonts and images load) before taking the screenshot.
  Gotenberg form fields used by the workflow: width, height, clip=true, format, failOnConsoleExceptions=true,
  waitForExpression="document.body.getAttribute('data-ready') === '1' || document.body.hasAttribute('data-error')".
  A failed image sets data-error and throws, so the render fails instead of publishing a blank frame.

  Spec: mycrystalcode-content/agency/C-design-system.md (sections 1-3). Colors come from the
  site's tokens.css; nothing outside that palette is used.

  Slide JSON (fields by layout):
    common   { lang: "en"|"ar", layout, index, total, eyebrow? }
    cover    { headline, sub?, glyph?: "transmutation"|"seed"|"metatron"|"crystal" }
    statement{ statement, support? }
    list     { title, items: [{ text, sub? }] }            3-5 items
    quote    { question, prompt? }
    split    { behavior, reasons: [string, string, string] }
    centers  { title?, centers: [{ key, name, state, note }] }   state: care|working|rising|flowing
             one center = the single-center variant: { centers: [{ key, name, state, note, body }] }
    sample   { title, image, callout? }                   image: URL of a real lina-0X.webp page
    cta      { offer?: "both"|"lite"|"full", button? }
    reel_cover { eyebrow?, headline, image?, overlay? }   1080x1920; also used for each reel beat.
               overlay: true renders text + scrim on a transparent background (PNG with
               omitBackground) so mcc-reel can lay it over AI video.
  Wrap the emphasised last word(s) of a headline in *asterisks*.
-->
<html lang="en">
<head>
<meta name="viewport" content="width=1080">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;1,500&family=El+Messiri:wght@600;700&family=IBM+Plex+Sans+Arabic:wght@400;500;600&family=Inter:wght@400;500;600&family=Roboto+Mono:wght@500&display=block" rel="stylesheet">
