      if (d.overlay) {
        document.documentElement.classList.add('overlay');
        return '<section class="slide reel clear"><div class="scrim"></div><div class="rbox">' + (d.eyebrow ? '<div><span class="pill">' + esc(d.eyebrow) + '</span></div>' : '') +
