          '<div class="rbrand brand" style="color:#fdfcff">' + logo(36, 50, true) + 'My Crystal Code</div></section>';
      }
      return '<section class="slide scene reel">' + (d.image ? '<div class="bg" style="background-image:url(\'' + esc(d.image) + '\')"></div>' : stars(1920, d.index) + '<div class="layer" style="display:grid;place-items:center">' + seed(1000, '#b7a3e6', .25, .12) + '</div>') +
        '<div class="scrim"></div><div class="rbox">' + (d.eyebrow ? '<div><span class="pill">' + esc(d.eyebrow) + '</span></div>' : '') +
        '<h1 class="display headline balance" style="font-size:' + px + 'px">' + rich(d.headline) + '</h1></div>' +
        '<div class="rbrand brand" style="color:#fdfcff">' + logo(36, 50, true) + 'My Crystal Code</div></section>';
    }
  };

  var render = L[d.layout] || L.cover;
  document.getElementById('root').innerHTML = render();
  // The renderer waits for this flag, so fallback fonts never reach a published slide.
  // Fail closed: a missing image throws (Gotenberg's failOnConsoleExceptions rejects the render)
  // and the ready flag is never set, so a slide with a blank frame cannot be published.
  var imgs = Array.prototype.slice.call(document.images).map(function (im) {
    return new Promise(function (ok, ko) {
      if (im.complete && im.naturalWidth) return ok();
      im.onload = ok;
      im.onerror = function () { ko(new Error('MCC image failed to load: ' + String(im.src).slice(0, 120))); };
    });
  });
  Promise.all([document.fonts.ready].concat(imgs)).then(function () { document.body.setAttribute('data-ready', '1'); },
    function (e) { document.body.setAttribute('data-error', e.message); setTimeout(function () { throw e; }); });
})();
