";
const S = $('⚙️ Settings').first().json;
const { post } = $input.first().json;
const overlay = S.REEL_TIER === 'premium';
return post.beats.map((b, i) => {
  const slide = { layout: 'reel_cover', lang: post.lang, index: i + 1, headline: b.text, overlay };
  const html = TEMPLATE.replace('__MCC_DATA__', JSON.stringify(slide).replace(/<//g, '<\/'));
  return { json: { n: i + 1, omit_background: overlay ? 'true' : 'false' }, binary: { data: { data: Buffer.from(html).toString('base64'), mimeType: 'text/html', fileName: 'index.html' } } };
});

// Gathers the 5 rendered beat frames onto one item (beat_1..beat_5) with their durations.
const items = $input.all();
const post = $('Format?').first().json.post;
const binary = {};
items.forEach((it, i) => { binary[`beat_${i + 1}`] = it.binary.data; });
return [{ json: { post, durations: JSON.stringify(post.beats.map((b) => Number(b.seconds) || 3)) }, binary }];

// Puts the beat frames, the voiceover and (premium) the AI clip URL on one item for mcc-reel.
const beats = $('Collect beats').first();
let voice;
try { voice = $('Voiceover (ElevenLabs)').first().binary.data; } catch (e) { voice = undefined; }
if (!voice) throw new Error('Voiceover is missing: refusing to assemble a silent reel.');
let clipUrl = '';
try { clipUrl = $('fal: result').first().json.video?.url || ''; } catch (e) { clipUrl = ''; }
return [{ json: { ...beats.json, clip_url: clipUrl }, binary: { ...beats.binary, voice } }];

// Re-attaches the beat frames (for visual QA) next to the finished video.
const inputs = $('Assemble reel inputs').first();
const binary = { video: $input.first().binary.data };
Object.keys(inputs.binary).filter((k) => k.startsWith('beat_')).forEach((k) => { binary[k] = inputs.binary[k]; });
const keys = Object.keys(binary).filter((k) => k.startsWith('beat_')).sort();
return [{ json: { post: inputs.json.post, clip_url: inputs.json.clip_url, qa_keys: keys, media_type: 'image/png' }, binary }];

// Gate B (agency/C §5): a vision model checks the rendered slides or reel frames against the
// brand-guardian checklist. Builds the Anthropic Messages API request; the binaries are passed
// through so later nodes can still publish them.
const S = $('⚙️ Settings').first().json;
const item = $input.first();
const { post, qa_keys: keys, media_type: mediaType } = item.json;
const CHECKLIST = "| ID | Check | Sev |\n|---|---|---|\n| B1 | All expected text present, exact, unclipped, not overflowing its box; no ellipsis | H |\n| B2 | No text, logo or key object inside the reserved zones: top-right 150×110 (carousel) / outside the universal reel box (reels) / within 34px of left/right edges (covers) | H |\n| B3 | Every text line is legible at a 360px-wide thumbnail (simulate a downscale to 33%) | H |\n| B4 | No stray, garbled or AI-generated text/letters/script in imagery | H |\n| B5 | Arabic: right-aligned or centred as specified, letters joined (no gaps or isolated forms), no tofu boxes, `$`/`@` runs not displaced, counters in Eastern digits | H |\n| B6 | Background is near-black scene or warm paper; **no pale lavender-grey or misty lilac wash covering > 25% of the slide** | H |\n| B7 | Brand gradient appears at most once and never as a full-bleed background; no text sits over its teal end | S |\n| B8 | Exactly one owned geometry/logo mark style used; no distorted logo (aspect 500:690 kept) | S |\n| B9 | Display font is a high-contrast serif (EN) / El Messiri (AR); body is a clean sans; no system fallback look | H |\n| B10 | Chakra rainbow or state colours appear only on an energy-centre slide | S |\n| B11 | No religious or cultural symbols (Om, deities, crescent, scripture, hamsa, cross, prayer beads) | H |\n| B12 | People: hands/partial figures dignified, correct anatomy (5 fingers), no uncanny or waxy faces, no clone faces, modest and non-sexualised, not exoticised | H |\n| B13 | No medical, money-pile or fear imagery; no implied guarantee in visuals | H |\n| B14 | Sample slides show the \"illustrative sample / fictional\" label; energy slides show the \"not a medical measurement\" footnote; CTA shows the disclaimer | H |\n| B15 | Footer: logo and handle present and readable (except L1/L4 per spec), mirrored sides in AR | S |\n| B16 | One clear focal point; text block does not compete with an equally bright image area | S |\n| B17 | Glows are saturated purple/teal or warm amber; highlights warm, not cyan-white | S |\n| B18 | Reels: caption ≤ 2 lines, inside y 1030–1240, readable against footage (pill or shadow present) | H |\n| B19 | Cover (L1 / reel cover): headline is the largest element and reads in < 2 seconds; gradient emphasis word present | S |\n| B20 | Overall impression \"calm, premium, intelligent\", not loud, hype-y or woo-woo (justify in the note) | S |";
const content = [];
for (const key of keys) {
  const buf = await this.helpers.getBinaryDataBuffer(0, key);
  content.push({ type: 'image', source: { type: 'base64', media_type: mediaType, data: buf.toString('base64') } });
}
const expected = post.format === 'carousel'
  ? post.slides.map((s, i) => `Slide ${i + 1} [${s.layout}]: ${JSON.stringify(s)}`).join('\n')
  : post.beats.map((b, i) => `Frame ${i + 1}: ${b.text}`).join('\n');
content.push({ type: 'text', text: `You are My Crystal Code's brand guardian. The ${keys.length} images above are the rendered ${post.format === 'carousel' ? 'carousel slides (1080x1350)' : 'reel text frames (1080x1920; transparent areas will show video)'} of one ${post.lang === 'ar' ? 'Arabic' : 'English'} post, in order.

Expected content (asterisks mark the gradient-emphasis words, they are not printed):
${expected}

Evaluate the whole set against each checklist item. Items marked [H] are hard; [S] are soft. Skip items that cannot apply to this format and mark them pass.
${CHECKLIST}

Answer ONLY with JSON, no prose and no code fences:
{"items":[{"id":"B1","pass":true,"note":""}],"verdict":"pass|fail"}
verdict is "fail" if any [H] item fails or two or more [S] items fail.` });
const body = { model: S.QA_MODEL, max_tokens: 2000, messages: [{ role: 'user', content }] };
return [{ json: { post, qa_body: JSON.stringify(body) }, binary: item.binary }];

// Parses the vision verdict. Unparseable output counts as a fail (fail closed).
const req = $('QA request').first();
const res = $input.first().json;
const text = (res.content || []).filter((c) => c.type === 'text').map((c) => c.text).join('').trim();
let v;
try { v = JSON.parse(text.replace(/^```(json)?|```$/g, '').trim()); } catch (e) { v = null; }
const post = req.json.post;
if (!v || !Array.isArray(v.items)) {
  return [{ json: { ok: false, stage: 'visual_qa', post, issues: ['Visual QA returned unparseable output (treated as a fail).'] }, binary: req.binary }];
}
const failed = v.items.filter((i) => !i.pass);
return [{ json: {
  ok: v.verdict === 'pass', stage: 'visual_qa', post, qa: v,
  issues: failed.map((i) => `${i.id}: ${i.note || 'failed'}`),
}, binary: req.binary }];

